import{c as a,Q as i,j as t,m as s}from"./chunks/framework.7r1mYKiJ.js";const g=JSON.parse('{"title":"World Generation","description":"","frontmatter":{},"headers":[],"relativePath":"features/world-generation.md","filePath":"features/world-generation.md"}'),n={name:"features/world-generation.md"};function r(o,e,l,h,d,c){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="world-generation" tabindex="-1">World Generation <a class="header-anchor" href="#world-generation" aria-label="Permalink to &quot;World Generation&quot;">​</a></h1><p>AetherUHC features a highly optimized, fully integrated World Pre-Generation engine. Rather than relying on external plugins like FastAsyncWorldEdit or Chunky, AetherUHC automatically handles everything.</p><p>Map pre-generation ensures that all chunks within your configured border are generated and saved to disk <em>before</em> players drop in, completely eliminating server lag from on-the-fly chunk loading.</p><h2 id="configuring-the-generator" tabindex="-1">Configuring the Generator <a class="header-anchor" href="#configuring-the-generator" aria-label="Permalink to &quot;Configuring the Generator&quot;">​</a></h2><p>In <code>plugins/AetherUHC/worldmanagement.yml</code>, you will find the <code>CHUNK-PREGENERATION</code> section:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">CHUNK-PREGENERATION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  PREGEN-MODE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">async</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  SAVE-INTERVAL-SECONDS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span></span></code></pre></div><ul><li><strong><code>PREGEN-MODE: async</code></strong>: (Recommended for Modern 1.20+ servers). This uses Paper&#39;s multithreaded chunk loader to generate chunks across all CPU cores incredibly fast without crashing the main thread.</li><li><strong><code>PREGEN-MODE: sync</code></strong>: (Recommended for Legacy 1.8 servers). This runs a linear row-scan over the map on the main thread, constrained by a strict milliseconds-per-tick budget to keep the server online.</li></ul><h2 id="setting-the-border-size" tabindex="-1">Setting the Border Size <a class="header-anchor" href="#setting-the-border-size" aria-label="Permalink to &quot;Setting the Border Size&quot;">​</a></h2><p>The pre-generator determines how many chunks to generate based on the <code>BORDER.START</code> configuration in your <code>uhcconfiguration.yml</code>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>A standard UHC border is <strong>2000 blocks</strong> (radius). This gives a perfectly clean 125-chunk radius, meaning exactly 63,001 chunks will be generated. We highly recommend using borders divisible by 16 to prevent math rounding issues.</p></div><h2 id="custom-generators" tabindex="-1">Custom Generators <a class="header-anchor" href="#custom-generators" aria-label="Permalink to &quot;Custom Generators&quot;">​</a></h2><p>AetherUHC supports custom chunk generation plugins! If you specify a generator in the config, AetherUHC will automatically hook it and use it during the pre-gen phase.</p><h3 id="beta-1-7-3-generation" tabindex="-1">Beta 1.7.3 Generation <a class="header-anchor" href="#beta-1-7-3-generation" aria-label="Permalink to &quot;Beta 1.7.3 Generation&quot;">​</a></h3><p>For authentic legacy terrain (with crazy mountains, unpredictable caves, and large flat plains), you can enable the included Beta 1.7.3 terrain engine.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">WORLD-GENERATOR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;BETA173&quot;</span></span></code></pre></div><h3 id="cityworld" tabindex="-1">CityWorld <a class="header-anchor" href="#cityworld" aria-label="Permalink to &quot;CityWorld&quot;">​</a></h3><p>If you have the <code>CityWorld</code> plugin installed alongside AetherUHC, you can force the map to generate as an abandoned concrete metropolis.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">WORLD-GENERATOR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CityWorld&quot;</span></span></code></pre></div><h3 id="vanilla" tabindex="-1">Vanilla <a class="header-anchor" href="#vanilla" aria-label="Permalink to &quot;Vanilla&quot;">​</a></h3><p>For standard Minecraft terrain (with the No-Oceans datapack injected on modern versions):</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">WORLD-GENERATOR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;VANILLA&quot;</span></span></code></pre></div><h2 id="how-to-pregen-a-map" tabindex="-1">How to Pregen a Map <a class="header-anchor" href="#how-to-pregen-a-map" aria-label="Permalink to &quot;How to Pregen a Map&quot;">​</a></h2><ol><li>Stop your server.</li><li>Delete the old <code>world/</code> folder (or your specific UHC world folder).</li><li>Ensure <code>UHC-WORLD-USED: true</code> is set in <code>uhcconfiguration.yml</code>. (This tells the plugin it&#39;s a fresh deployment).</li><li>Start the server. The console will automatically begin logging the pregen progress.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Do NOT let players join while the pre-generation is running, as it will drastically slow down the process and create severe lag.</p></div>`,24)])])}const u=a(n,[["render",r]]);export{g as __pageData,u as default};
